/* MediGO — private, local-first health record and report builder. */
const KEY = "medigo-data-v1";
const today = new Date().toISOString().slice(0, 10);
const TRACKERS = ["Weight", "Blood pressure", "Blood glucose", "Water", "Waist", "Calories", "Mood", "Symptom"];
const SECTIONS = [["profile", "Profile & emergency info", "Name, age, blood group, allergies, contacts"], ["conditions", "Conditions", "The health categories you track"], ["medications", "Current medications & adherence", "Dose, schedule, taken/missed/skipped"], ["vitals", "Vitals per condition", "Summary stats and trend chart per vital"], ["bmi", "BMI & weight", "Latest weight, BMI and trend"], ["mood", "Mood summary", "Average mood and low-mood days"], ["symptoms", "Symptoms & notes", "Free-text entries"], ["questions", "Questions for doctor", "Only the questions you checked"], ["notes", "Visit notes", "Advice from previous visits"], ["documents", "Attached documents", "Images inline, PDFs listed"]];
const empty = () => ({ disclaimerAccepted: false, settings: { largeText: false, highContrast: false, weight: "kg", height: "cm", glucose: "mg/dL", asianBmi: true }, profiles: [], activeProfileId: null });
let data = load(), page = data.profiles.length ? "home" : "landing", doctorTab = "doctors", tracker = "Weight", range = 30, tableMode = false, modal = "";

function load() { try { const x = JSON.parse(localStorage.getItem(KEY)) || empty(); x.settings = { ...empty().settings, ...(x.settings || {}) }; x.profiles = (x.profiles || []).map(old => { const entries = old.entries || old.trackerEntries || old.readings || []; return { ...old, conditions: old.conditions || old.categories || [], contacts: old.contacts || [], allergies: old.allergies || "", medications: (old.medications || []).map(m => ({ ...m, dose: m.dose || m.strength || "", frequency: m.frequency || m.schedule || "Daily", times: m.times || [] })), doses: old.doses || {}, entries: entries.map(e => ({ ...e, tracker: ({ weight: "Weight", bp: "Blood pressure", glucose: "Blood glucose", "blood pressure": "Blood pressure", "blood glucose": "Blood glucose", waist: "Waist", calories: "Calories", mood: "Mood", symptom: "Symptom", water: "Water" })[String(e.tracker || e.type || "").toLowerCase()] || e.tracker || e.type || "Weight" })), waterGoal: old.waterGoal || 2000, doctors: (old.doctors || []).map(d => ({ ...d, specialty: d.specialty || "", phone: d.phone || d.note || "", notes: d.notes || "" })), questions: old.questions || [], visitNotes: old.visitNotes || [], documents: old.documents || [] }; }); return x; } catch { return empty(); } }
function save() { try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { alert("MediGO could not save this change. Check available device storage."); } }
const p = () => data.profiles.find(x => x.id === data.activeProfileId);
const uid = () => crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
const esc = x => String(x ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[c]));
const fmtDate = d => new Date(`${d}T12:00:00`).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
const entryName = t => t === "Blood pressure" ? "BP" : t;
function render() { document.body.classList.toggle("large-text", data.settings.largeText); document.body.classList.toggle("high-contrast", data.settings.highContrast); const app = document.querySelector("#app"); app.innerHTML = page === "landing" ? landing() : page === "welcome" ? welcome() : page === "setup" ? setup() : shell(); wire(); }

function landing() { return `<header class="site-header"><a class="wordmark" href="#top" data-action="top"><span class="logo-mark">M</span>MediGO</a><nav><a href="#features">Features</a><a href="#how-it-works">How it works</a><a href="#privacy">Privacy</a><a href="#faq">FAQ</a></nav><button class="button secondary" data-action="open-app">Open app</button></header><main id="top"><section class="hero container"><div><span class="eyebrow pill">Free · Offline · No sign-up to try</span><h1>Every visit,<br><em>one clear page.</em></h1><p>Log vitals, medications, and moods in seconds. MediGO quietly turns them into a printable report and a doctor-ready QR summary — stored only on your device.</p><div class="actions"><button class="button" data-action="start-profile">Start tracking free <span>→</span></button><a class="button secondary" href="#how-it-works">See how reports work</a></div><small class="muted">No account required to try · Your data stays on this device.</small></div><div class="hero-art"><div class="report-card"><div class="report-top"><span class="logo-mark">M</span><div><b>MediGO Health Profile</b><small>Your health, organized</small></div><span class="status-dot">●</span></div><div class="report-date">A simple summary for your next visit</div><div class="stats"><div><small>Blood pressure</small><b>— / —</b><span>mmHg</span></div><div><small>Glucose</small><b>—</b><span>mg/dL</span></div><div><small>Adherence</small><b>—</b><span>from your records</span></div></div><div class="report-chart"><span style="height:30%"></span><span style="height:46%"></span><span style="height:38%"></span><span style="height:66%"></span><span style="height:58%"></span><span style="height:84%"></span><span style="height:73%"></span></div><div class="qr-row"><div class="qr-placeholder">▦</div><div><b>Your doctor-ready summary</b><small>Review before you share</small></div></div></div><div class="floating-note">✦ <span>Works offline</span></div></div></section><div class="trust-strip"><span>◉ Works fully offline</span><span>⌑ Data stays on-device</span><span>↗ Export anytime</span><span>♡ Free, always</span></div><section class="section container" id="features"><span class="eyebrow">WHAT IT DOES</span><h2>Six habits, one<br>unified checklist.</h2><p class="section-intro">Everything a chronic condition asks you to remember, collected once and reused everywhere — on your phone at home and on a single page at the clinic.</p><div class="feature-grid">${[["✓", "Today Checklist", "One tracker per vital, no duplicates — even when you’re managing more than one condition."], ["♡", "Medication Adherence", "Dose cards with Taken, Skip and Snooze. MediGO calculates adherence from what you record."], ["＋", "Doctors & Visit Notes", "Keep every doctor, question for your next visit, advice note and lab document in one place."], ["⌁", "Analytics", "Weight, blood pressure, glucose and mood trends you can review over time."], ["▤", "Doctor-Ready Report", "A printable health profile with summary stats, charts and a QR code for the consult room."], ["♧", "Private by Design", "Your records live on this device and export to a file whenever you want."]].map(([i, h, d]) => `<article class="feature-card"><span class="feature-icon">${i}</span><h3>${h}</h3><p>${d}</p></article>`).join("")}</div></section><section class="section how-section" id="how-it-works"><div class="container how-grid"><div><span class="eyebrow">A CLOSER LOOK</span><h2>Small steps.<br>Clearer visits.</h2><p class="muted">Log your day and MediGO organizes the details into a calm, readable report.</p><button class="button" data-action="start-profile">Create your profile →</button></div><div class="mini-dashboard"><div class="mini-head">Today <span>Today’s checklist</span></div><div class="mini-item"><i>⚖</i><b>Weight</b><small>Not logged yet</small><button data-action="start-profile">Log</button></div><div class="mini-item"><i>♡</i><b>Blood pressure</b><small>Not logged yet</small><button data-action="start-profile">Log</button></div><div class="mini-item"><i>◉</i><b>Medication</b><small>Due doses appear here</small><button data-action="start-profile">View</button></div><div class="mini-foot">You log your day… <b>MediGO quietly organizes it…</b> …into one page for your doctor.</div></div></div></section><section class="section container privacy-section" id="privacy"><span class="eyebrow">PRIVATE BY DESIGN</span><h2>Your data stays exactly<br>where you put it.</h2><p class="section-intro">Health data is personal. MediGO is built to keep your records on your device, with backup and export tools under your control.</p><div class="privacy-grid"><article><h3>Stored on-device</h3><p>Your profiles, readings and documents live in this browser.</p></article><article><h3>Works offline</h3><p>Once loaded, core records remain available without a connection.</p></article><article><h3>Export anytime</h3><p>Download your records as a JSON backup whenever you choose.</p></article></div></section><section class="section faq-section" id="faq"><div class="container"><span class="eyebrow">GOOD TO KNOW</span><h2>Frequently asked questions</h2><details><summary>Do I need an account?</summary><p>No account is needed to try the local app. Records are stored in this browser.</p></details><details><summary>Is MediGO medical advice?</summary><p>No. It records what you enter and gives you a readable form to review with your doctor.</p></details><details><summary>What is on the QR code?</summary><p>A short plain-text summary of the sections you select. Anyone who scans it can read that summary, so review it before sharing.</p></details><details><summary>Can I use it offline?</summary><p>Yes. The app shell and your local records are designed to work on this device without a network connection.</p></details></div></section><section class="final-cta"><div class="container"><span class="eyebrow">YOUR NEXT VISIT, A LITTLE EASIER</span><h2>Build your first report<br>in under two minutes.</h2><p>Free, offline and yours. Start with one reading — the report takes shape as you go.</p><button class="button" data-action="start-profile">Create my profile →</button></div></section></main><footer class="site-footer container"><a class="wordmark" href="#top"><span class="logo-mark">M</span>MediGO</a><span>Your health, your page, your device.</span><small>© 2026 MediGO · Patient-entered data. Not a diagnosis.</small></footer>`; }
function welcome() { return `<section class="content"><div class="container narrow"><button class="text-button" data-action="landing">← Back to overview</button><p class="eyebrow">PRIVATE HEALTH RECORDS</p><h1>Your health record,<br>ready for the next appointment.</h1><p class="muted">Log vitals and doses in seconds, keep every doctor visit in one place, and walk in with a one-page report instead of scraps of notes.</p><div class="notice"><b>Personal record-keeping tool</b><p>MediGO does not diagnose, treat or give medical advice. Everything you enter is stored on this device. In an emergency, contact your local emergency number or doctor directly.</p></div><div class="card" style="margin-top:18px"><h2>Start with a profile</h2><p class="muted">No account required for this local version. Your profile and records stay in this browser.</p><label class="check"><input id="accept-disclaimer" type="checkbox"> I understand this is a personal record-keeping tool.</label><div class="actions"><button class="button" data-action="continue" disabled>Continue</button></div></div></div></section>`; }
function setup() { return `<section class="content"><div class="container narrow"><button class="text-button" data-action="landing">← Cancel</button><p class="eyebrow">FIRST-TIME SETUP</p><h1>Who is this profile for?</h1><form id="setup-form" class="card form"><label>Profile name<input name="name" required placeholder="Name"></label><div class="form-row"><label>Date of birth<input name="dob" type="date"></label><label>Blood group<select name="blood"><option value="">Not specified</option>${["A+", "A−", "B+", "B−", "AB+", "AB−", "O+", "O−"].map(v => `<option>${v}</option>`).join("")}</select></label></div><label>Conditions or health categories<input name="conditions" placeholder="Optional, separate with commas"></label><label>Allergies<input name="allergies" placeholder="None recorded"></label><label class="check"><input name="guardian" type="checkbox"> I help manage this profile for someone else.</label><button class="button">Create profile</button></form></div></section>`; }

function shell() { if (!p()) { page = "landing"; return landing(); } const profile = p(); const nav = [["home", "⌂", "Home"], ["doctors", "♧", "Doctors"], ["analytics", "▥", "Analytics"], ["report", "▤", "Report"]]; return `<header class="app-top"><button class="profile-switch" data-action="profiles"><span class="avatar">${esc(profile.name.slice(0, 1).toUpperCase())}</span><span><b>${esc(profile.name)}</b><small>${profile.dob ? `${age(profile.dob)} years` : "Personal health profile"}</small></span><span class="chevron">⌄</span></button><button class="settings-button" data-page="settings" aria-label="Settings">⚙</button></header><main class="content app-content container">${pageView()}</main><nav class="bottom-nav" aria-label="Primary">${nav.map(([k, icon, label]) => `<button class="nav-button ${page === k || (k === "doctors" && page === "medications") ? "active" : ""}" data-page="${k}" aria-current="${page === k ? "page" : "false"}"><span>${icon}</span>${label}</button>`).join("")}</nav>${modalView()}`; }
function age(dob) { const d = new Date(dob); let a = new Date().getFullYear() - d.getFullYear(); if (new Date() < new Date(new Date().getFullYear(), d.getMonth(), d.getDate())) a--; return a; }
function pageView() { return ({ home: homeView, doctors: doctorsView, medications: medicationsView, analytics: analyticsView, report: reportView, settings: settingsView, log: logView }[page] || homeView)(); }
function homeView() { const x = p(), due = ["Weight", "Blood pressure", "Blood glucose", "Water"]; const todays = x.entries.filter(e => e.date === today); const logs = new Set(todays.map(e => e.tracker)); const dueMeds = x.medications.filter(m => !m.end || m.end >= today); return `<div class="page-title"><div><h1>Today</h1><p>${fmtDate(today)} · ${esc(x.name)}</p></div><button class="button secondary" data-page="analytics">⌁　Trends</button></div><h2 class="section-label">Due today</h2><div class="due-row">${due.slice(0, 3).map(t => `<button class="due-card" data-log="${t}"><small>Suggested</small><b>Log ${entryName(t)}</b><span>${logs.has(t) ? "Logged today" : "Not logged yet today"}</span></button>`).join("")}<button class="due-card" data-water="250"><small>Daily target</small><b>Water</b><span>${Number(x.waterTotal || 0)} / ${x.waterGoal} ml today</span></button>${dueMeds.length ? `<button class="due-card" data-page="medications"><small>Medication</small><b>${dueMeds.length} dose${dueMeds.length === 1 ? "" : "s"} due</b><span>Record dose status</span></button>` : ""}</div><section class="card checklist-card"><h2>Today’s checklist</h2><div class="checklist-grid">${[...TRACKERS.filter(t => !["Water"].includes(t)), "Water"].map(t => { const e = todays.find(z => z.tracker === t); return `<div class="checklist-item"><span class="tracker-icon">${icon(t)}</span><span><b>${entryName(t)}</b><small>${e ? esc(e.value) : "Not logged yet today"}</small></span><button class="button secondary" data-log="${t}">${t === "Water" ? "Add" : "Log"}</button></div>`; }).join("")}</div></section><section class="card"><div class="card-heading"><h2>Logged today</h2><button class="text-button" data-page="analytics">All history →</button></div>${todays.length ? todays.slice().reverse().map(e => `<div class="entry-row"><span><b>${entryName(e.tracker)}</b><small>${fmtDate(e.date)} · ${esc(e.time || "")}</small></span><strong>${esc(e.value)} ${esc(e.unit || "")}</strong><button class="icon-button" data-edit="${e.id}" aria-label="Edit entry">✎</button><button class="icon-button danger-text" data-delete-entry="${e.id}" aria-label="Delete entry">×</button></div>`).join("") : `<p class="empty">Your logged entries will appear here.</p>`}</section><section class="card"><div class="card-heading"><h2>Care team</h2><button class="text-button" data-page="doctors">Open →</button></div>${x.doctors.length ? x.doctors.map(d => `<p><b>${esc(d.name)}</b> · ${esc(d.specialty || d.clinic || "Doctor")}</p>`).join("") : `<p class="empty">No doctor saved. Add one so questions and visit notes have a home.</p><button class="button secondary" data-page="doctors">Add a doctor</button>`}</section>`; }
function icon(t) { return ({ Weight: "⚖", "Blood pressure": "♡", "Blood glucose": "◉", Water: "♢", Waist: "⌁", Calories: "✳", Mood: "☺", Symptom: "＋" })[t] || "•"; }
function logView(prefill = "") { const x = p(); return `<div class="page-title"><div><h1>Log an entry</h1><p>Record what you want to remember.</p></div></div><section class="card"><form id="entry-form" class="form"><div class="form-row"><label>Tracker<select name="tracker">${TRACKERS.map(t => `<option ${t === (prefill || tracker) ? "selected" : ""}>${t}</option>`).join("")}</select></label><label>Value<input name="value" required placeholder="Enter a reading or note"></label></div><div class="form-row"><label>Date<input name="date" type="date" value="${today}" required></label><label>Context (optional)<input name="note" placeholder="For example, before breakfast"></label></div><button class="button">Save entry</button></form></section><section class="card"><h2>Recent entries</h2>${x.entries.slice().reverse().slice(0, 12).map(e => `<div class="entry-row"><span><b>${entryName(e.tracker)}</b><small>${fmtDate(e.date)} · ${esc(e.note)}</small></span><strong>${esc(e.value)}</strong></div>`).join("") || `<p class="empty">Nothing recorded yet.</p>`}</section>`; }
function doctorsView() { const x = p(); const tabs = [["doctors", "Doctors"], ["visits", "Visit notes"], ["questions", "Questions"], ["documents", `Documents (${x.documents.length})`]]; let content = ""; if (doctorTab === "doctors") content = `<div class="card-heading"><h2>Your doctors</h2><button class="button" data-modal="doctor">＋ Add doctor</button></div>${x.doctors.length ? x.doctors.map(d => `<article class="doctor-card"><div class="card-heading"><span class="avatar">${esc(d.name.slice(0, 1))}</span><button class="icon-button danger-text" data-remove-doctor="${d.id}" aria-label="Remove doctor">×</button></div><h3>${esc(d.name)}</h3><p class="muted">${esc(d.specialty || "")}${d.clinic ? ` · ${esc(d.clinic)}` : ""}</p>${d.phone ? `<p>${esc(d.phone)}</p>` : ""}${d.next ? `<small>Next appointment · ${fmtDate(d.next)}</small>` : ""}${d.notes ? `<p>${esc(d.notes)}</p>` : ""}</article>`).join("") : `<div class="empty-state"><span>♧</span><h3>No doctors yet</h3><p>Save your doctor’s clinic and phone number so your care information is easy to find.</p><button class="button secondary" data-modal="doctor">Add doctor</button></div>`}`;
 if (doctorTab === "visits") content = `<div class="card-heading"><h2>Visit notes</h2><button class="button" data-modal="visit">＋ Add visit note</button></div>${x.visitNotes.length ? x.visitNotes.slice().reverse().map(n => `<article class="note-card"><small>${fmtDate(n.date)}</small><h3>${esc(n.doctor || "Visit note")}</h3><p>${esc(n.text)}</p></article>`).join("") : `<div class="empty-state"><span>▤</span><h3>No visit notes yet</h3><p>Write what your doctor said, and what changed, while it is fresh.</p><button class="button secondary" data-modal="visit">Add visit note</button></div>`}`;
 if (doctorTab === "questions") content = `<div class="card-heading"><h2>Ask at the next visit</h2></div><form id="question-form" class="question-form"><input name="question" placeholder="New question for the doctor" required><button class="button">Add</button></form>${x.questions.length ? x.questions.map(q => `<div class="question-row"><label class="check"><input type="checkbox" data-ready="${q.id}" ${q.ready ? "checked" : ""}><span>${esc(q.text)}</span></label><button class="icon-button danger-text" data-remove-question="${q.id}" aria-label="Remove question">×</button></div>`).join("") : `<div class="empty-state"><span>？</span><h3>No questions yet</h3><p>Park questions here as they come to you — choose the ones you want to include in your report.</p></div>`}`;
 if (doctorTab === "documents") content = `<div class="card-heading"><h2>Add a document</h2></div><form id="document-form" class="form document-form"><label>Category<select name="category"><option>Lab</option><option>Prescription</option><option>Scan</option><option>Other</option></select></label><label>Label (optional)<input name="label"></label><label>Document date<input name="date" type="date" value="${today}"></label><label class="upload-box">＋ Choose PDF or photo (max 5 MB)<input name="file" type="file" accept="image/*,.pdf" hidden></label><button class="button">Save document</button></form><p class="muted small-note">Files are saved on this device only.</p><h3>Saved documents · ${x.documents.length} of 20</h3>${x.documents.length ? x.documents.map(d => `<div class="entry-row"><span><b>${esc(d.label || d.name)}</b><small>${esc(d.category)} · ${fmtDate(d.date)} · ${Math.round(d.size / 1024)} KB</small></span><button class="button secondary" data-view-doc="${d.id}">View</button><button class="icon-button danger-text" data-remove-doc="${d.id}" aria-label="Delete document">×</button></div>`).join("") : `<p class="empty">No documents saved yet.</p>`}`;
 return `<div class="page-title"><div><h1>Doctors</h1><p>People, questions and notes for your care.</p></div></div><div class="tabs">${tabs.map(([k, label]) => `<button class="tab ${doctorTab === k ? "active" : ""}" data-doctor-tab="${k}">${label}</button>`).join("")}</div><section class="card">${content}</section>`; }

function medicationsView() { const x = p(); return `<div class="page-title"><div><h1>Medications</h1><p>Adherence appears once you record dose statuses.</p></div><button class="button" data-modal="medication">＋ Add medication</button></div>${x.medications.length ? `<section class="card"><h2>Today’s doses</h2>${x.medications.map(m => { const status = x.doses[`${today}:${m.id}`] || "not recorded"; return `<div class="med-card"><div class="card-heading"><span><b>${esc(m.name)}</b><small>${esc(m.dose)}${m.form ? ` · ${esc(m.form)}` : ""}</small></span><span class="status-label ${status}">${esc(status)}</span></div><p class="muted">${esc(m.frequency)} · ${(m.times || []).map(esc).join(", ")}</p><div class="actions compact"><button class="button ${status === "taken" ? "" : "secondary"}" data-dose="${m.id}" data-status="taken">Taken</button><button class="button ghost" data-dose="${m.id}" data-status="skipped">Skip</button><button class="button ghost" data-dose="${m.id}" data-status="snoozed">Snooze</button></div></div>`; }).join("")}</section><section class="card"><h2>Saved medications</h2>${x.medications.map(m => `<div class="entry-row"><span><b>${esc(m.name)}</b><small>${esc(m.dose)} · ${esc(m.purpose || "")}</small></span><button class="icon-button danger-text" data-remove-med="${m.id}" aria-label="Remove medication">×</button></div>`).join("")}</section>` : `<section class="card empty-state"><span>＋</span><h2>No medications yet</h2><p>Add a medication with its schedule and MediGO builds today’s dose list for you.</p><button class="button" data-modal="medication">Add medication</button></section>`}`; }

function analyticsView() { const x = p(), end = new Date(`${today}T12:00:00`), start = new Date(end); start.setDate(end.getDate() - (range === "custom" ? 30 : range) + 1); const defaultFrom = start.toISOString().slice(0, 10), from = range === "custom" ? (window.customRange?.[0] || defaultFrom) : defaultFrom, to = range === "custom" ? (window.customRange?.[1] || today) : today, selected = x.entries.filter(e => e.tracker === tracker && e.date >= from && e.date <= to); const nums = selected.map(e => Number.parseFloat(e.value)).filter(Number.isFinite); const latest = nums.length ? nums[0] : null, avg = nums.length ? nums.reduce((a, b) => a + b, 0) / nums.length : null; const items = ["Weight", "Blood glucose", "Water", "Waist", "Calories", "Mood", "Blood pressure", "Symptom"]; return `<div class="page-title"><div><h1>Analytics</h1><p>${range === "custom" ? "Custom range" : `Last ${range} days`}</p></div><button class="button secondary" data-action="toggle-table">${tableMode ? "Chart view" : "Table view"}</button></div><section class="card"><div class="range-tabs">${[7, 30, 90].map(n => `<button class="tab ${range === n ? "active" : ""}" data-range="${n}">${n} days</button>`).join("")}<button class="tab ${range === "custom" ? "active" : ""}" data-range="custom">Custom</button></div>${range === "custom" ? `<div class="form-row custom-range"><label>From<input type="date" id="range-from" value="${from}"></label><label>To<input type="date" id="range-to" value="${to}"></label><button class="button secondary" data-action="apply-range">Apply</button></div>` : ""}<p class="muted">${fmtDate(from)} – ${fmtDate(to)}</p><div class="tracker-pills">${items.map(t => `<button class="tracker-pill ${tracker === t ? "active" : ""}" data-tracker="${t}">${icon(t)} ${t}</button>`).join("")}</div><h2>${esc(tracker)}</h2>${tableMode ? `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Value</th><th>Note</th></tr></thead><tbody>${selected.map(e => `<tr><td>${fmtDate(e.date)}</td><td>${esc(e.value)} ${esc(e.unit || "")}</td><td>${esc(e.note || "")}</td></tr>`).join("") || `<tr><td colspan="3">No entries in this range.</td></tr>`}</tbody></table></div>` : `<div class="chart" role="img" aria-label="${esc(tracker)} trend">${nums.slice().reverse().map((v, i) => `<div class="chart-bar" style="height:${Math.max(9, Math.min(100, v / (Math.max(...nums, 1)) * 100))}%"><b>${v}</b></div>`).join("") || `<p class="empty">Record numeric entries to see a trend.</p>`}</div>`}<div class="trend-summary">${[["Latest", latest === null ? "—" : `${latest} ${unit(tracker)}`], ["Average", avg === null ? "—" : `${avg.toFixed(1)} ${unit(tracker)}`], ["Min", nums.length ? Math.min(...nums) : "—"], ["Max", nums.length ? Math.max(...nums) : "—"], ["Count", selected.length]].map(([a, b]) => `<div><small>${a}</small><b>${b}</b></div>`).join("")}</div><p class="muted">Tap a point or row to review the original entry. Summaries describe your records and are not medical interpretations.</p></section><section class="card"><h2>Entries in this range</h2>${selected.length ? selected.slice().reverse().map(e => `<div class="entry-row"><span><b>${esc(e.value)} ${esc(e.unit || "")}</b><small>${fmtDate(e.date)} · ${esc(e.note || "")}</small></span><button class="icon-button" data-edit="${e.id}" aria-label="Edit entry">✎</button><button class="icon-button danger-text" data-delete-entry="${e.id}" aria-label="Delete entry">×</button></div>`).join("") : `<p class="empty">No ${esc(tracker.toLowerCase())} entries in this range.</p>`}</section>`; }
function unit(t) { if (t === "Weight") return data.settings.weight; if (t === "Blood glucose") return data.settings.glucose; if (t === "Waist") return data.settings.height; if (t === "Water") return "ml"; if (t === "Calories") return "kcal"; return ""; }

function reportView() { const x = p(), sel = new Set(JSON.parse(sessionStorage.getItem("medigo-sections") || '["profile","conditions","medications","vitals","bmi","questions"]')); const summary = summaryText(x, [...sel]); const preview = `<div class="report-paper"><div class="report-paper-head"><span class="logo-mark">M</span><div><h2>MediGO Profile Report</h2><small>${esc(x.name)} · Generated ${fmtDate(today)}</small></div><span class="report-badge">Patient-entered</span></div><p class="report-disclaimer">MediGO is a personal record-keeping tool. It does not diagnose, treat or give medical advice.</p>${[...sel].map(s => `<section class="report-section"><h3>${esc(sectionLabel(s))}</h3>${sectionText(x, s)}</section>`).join("")}<footer>Patient-entered data. Not a diagnosis. For doctor review.</footer></div>`; return `<div class="page-title"><div><h1>Report</h1><p>Last ${range} days · ${fmtDate(daysAgo(range === "custom" ? 90 : range))} – ${fmtDate(today)}</p></div><button class="button secondary" data-action="print">⎙　Print</button></div><section class="card"><h2>What goes in the report</h2><p class="muted">Choose the sections you want to include. Review everything before sharing.</p><div class="actions compact"><button class="text-button" data-action="all-sections">All</button><button class="text-button" data-action="no-sections">None</button></div><div class="report-options">${SECTIONS.map(([k, title, detail]) => `<label class="report-option"><input type="checkbox" data-section="${k}" ${sel.has(k) ? "checked" : ""}><span><b>${title}</b><small>${detail}</small></span></label>`).join("")}</div></section><section class="card"><div class="card-heading"><div><h2>QR summary</h2><p class="muted">Anyone who scans this QR can read the summary.</p></div><span class="character-count">${Math.min(900, summary.length)} / 900</span></div><div class="qr-summary"><div class="qr-placeholder">${qrPattern()}</div><div><b>Doctor-ready plain-text summary</b><small>Review the selected sections before sharing.</small></div></div><textarea id="qr-text" readonly>${esc(summary.slice(0, 900))}</textarea><div class="actions"><button class="button secondary" data-action="copy-qr">Copy text</button><button class="button ghost" data-action="download-qr">Download text</button><button class="button ghost" data-action="share">Share</button></div><details><summary>Show the plain-text summary</summary><p class="muted">${esc(summary.slice(0, 900))}</p></details></section><section class="card"><h2>Emergency card</h2><div class="emergency-card"><h3>${esc(x.name)}${x.dob ? ` · ${age(x.dob)} yrs` : ""}</h3><p>Blood group　${esc(x.blood || "Not recorded")}</p><p>Allergies　${esc(x.allergies || "None recorded")}</p><p>Conditions　${esc((x.conditions || []).join(", ") || "None recorded")}</p><p>Current medications　${esc(x.medications.map(m => m.name).join(", ") || "None recorded")}</p><p>Emergency contacts　${esc(x.contacts.map(c => c.name + (c.phone ? ` (${c.phone})` : "")).join(", ") || "None saved")}</p><button class="text-button" data-page="settings">Edit profile information →</button></div></section><section class="report-preview">${preview}</section>`; }
function daysAgo(n) { const d = new Date(`${today}T12:00:00`); d.setDate(d.getDate() - Number(n)); return d.toISOString().slice(0, 10); }
function qrPattern() { return `<span class="qr-grid">${Array.from({ length: 81 }, (_, i) => `<i class="${((i * 7 + Math.floor(i / 3) * 5) % 11 < 5 || [0, 1, 2, 9, 18, 19, 20, 6, 7, 8, 15, 16, 17, 54, 55, 56, 63, 64, 65, 72, 73, 74].includes(i)) ? "dark" : ""}"></i>`).join("")}</span>`; }
function sectionLabel(k) { return (SECTIONS.find(s => s[0] === k) || [k, k])[1]; }
function sectionText(x, k) { if (k === "profile") return `<p>${esc(x.name)}${x.dob ? ` · ${age(x.dob)} years` : ""} · Blood group ${esc(x.blood || "not recorded")}<br>Allergies: ${esc(x.allergies || "None recorded")}<br>Emergency contacts: ${esc(x.contacts.map(c => `${c.name} ${c.phone || ""}`).join(", ") || "None recorded")}</p>`; if (k === "conditions") return `<p>${esc(x.conditions.join(", ") || "No conditions recorded.")}</p>`; if (k === "medications") return `<p>${x.medications.map(m => `${esc(m.name)} ${esc(m.dose)} (${esc(m.frequency)})`).join("<br>") || "No active medications recorded."}</p>`; if (k === "vitals") return TRACKERS.filter(t => t !== "Symptom").map(t => { const a = x.entries.filter(e => e.tracker === t).slice(-30), v = a.map(e => parseFloat(e.value)).filter(Number.isFinite); return a.length ? `<p><b>${esc(t)}</b> · Latest ${esc(a[a.length - 1].value)} ${unit(t)} · Average ${v.length ? (v.reduce((q, z) => q + z, 0) / v.length).toFixed(1) : "—"} · ${a.length} entries</p>` : ""; }).join("") || "<p>No readings recorded.</p>"; if (k === "bmi") { const wt = [...x.entries].reverse().find(e => e.tracker === "Weight" && parseFloat(e.value)); const cm = Number(x.height); const bmi = wt && cm ? (Number(wt.value) / ((cm / 100) ** 2)).toFixed(1) : null; return `<p>Latest weight ${wt ? esc(wt.value) + " " + unit("Weight") : "Not recorded"}${bmi ? ` · BMI ${bmi} (reference only)` : ""}</p>`; } if (k === "mood") return `<p>${x.entries.filter(e => e.tracker === "Mood").map(e => `${esc(e.value)} · ${fmtDate(e.date)}`).join("<br>") || "No mood entries recorded."}</p>`; if (k === "symptoms") return `<p>${x.entries.filter(e => ["Symptom", "Mood"].includes(e.tracker)).map(e => `${esc(e.value)} · ${fmtDate(e.date)}`).join("<br>") || "No symptoms or notes recorded."}</p>`; if (k === "questions") return `<p>${x.questions.filter(q => q.ready).map(q => esc(q.text)).join("<br>") || "No questions marked as ready to ask."}</p>`; if (k === "notes") return `<p>${x.visitNotes.map(n => `${esc(n.text)} · ${fmtDate(n.date)}`).join("<br>") || "No visit notes recorded."}</p>`; return `<p>${x.documents.map(d => `${esc(d.label || d.name)} · ${esc(d.category)} · ${fmtDate(d.date)}`).join("<br>") || "No documents attached."}</p>`; }
function summaryText(x, sel) { const lines = [`MediGO summary for ${x.name}. Patient-entered reference data.`]; for (const k of sel) { const text = sectionText(x, k).replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim(); if (text) lines.push(`${sectionLabel(k)}: ${text}`); } return lines.join(" | "); }

function settingsView() { const x = p(); return `<div class="page-title"><div><h1>Settings</h1><p>${esc(x.name)}${x.dob ? ` · age ${age(x.dob)}` : ""}</p></div></div><section class="card"><h2>Profile & emergency information</h2><form id="profile-form" class="form settings-form"><div class="form-row"><label>Name<input name="name" value="${esc(x.name)}" required></label><label>Date of birth<input name="dob" type="date" value="${esc(x.dob || "")}"></label></div><div class="form-row"><label>Blood group<select name="blood"><option value="">Not specified</option>${["A+", "A−", "B+", "B−", "AB+", "AB−", "O+", "O−"].map(v => `<option ${x.blood === v ? "selected" : ""}>${v}</option>`).join("")}</select></label><label>Height (${data.settings.height})<input name="height" type="number" min="0" value="${esc(x.height || "")}"></label></div><label>Conditions<input name="conditions" value="${esc(x.conditions.join(", "))}" placeholder="Separate with commas"></label><label>Allergies<input name="allergies" value="${esc(x.allergies)}" placeholder="None recorded"></label><div class="card-heading"><h3>Emergency contacts</h3><button class="text-button" type="button" data-modal="contact">＋ Add contact</button></div>${x.contacts.map(c => `<div class="entry-row"><span><b>${esc(c.name)}</b><small>${esc(c.relationship || "")}${c.phone ? ` · ${esc(c.phone)}` : ""}</small></span><button type="button" class="icon-button danger-text" data-remove-contact="${c.id}">×</button></div>`).join("")}<button class="button">Save profile</button></form></section><div class="grid grid-2"><section class="card"><h2>Accessibility</h2><label class="check"><input id="large-text" type="checkbox" ${data.settings.largeText ? "checked" : ""}> Large text <small>Enlarges the app and tap targets.</small></label><label class="check"><input id="high-contrast" type="checkbox" ${data.settings.highContrast ? "checked" : ""}> High contrast <small>Strengthens text and borders.</small></label></section><section class="card"><h2>Units</h2><label>Weight<select name="weight-unit" data-unit="weight"><option value="kg" ${data.settings.weight === "kg" ? "selected" : ""}>Kilograms (kg)</option><option value="lb" ${data.settings.weight === "lb" ? "selected" : ""}>Pounds (lb)</option></select></label><label>Height<select data-unit="height"><option value="cm" ${data.settings.height === "cm" ? "selected" : ""}>Centimetres (cm)</option><option value="ft" ${data.settings.height === "ft" ? "selected" : ""}>Feet & inches</option></select></label><label>Glucose<select data-unit="glucose"><option value="mg/dL" ${data.settings.glucose === "mg/dL" ? "selected" : ""}>mg/dL</option><option value="mmol/L" ${data.settings.glucose === "mmol/L" ? "selected" : ""}>mmol/L</option></select></label><label class="check"><input id="asian-bmi" type="checkbox" ${data.settings.asianBmi ? "checked" : ""}> Asian BMI cut-offs</label><p class="muted">Display units do not change stored readings.</p></section></div><section class="card"><h2>Storage on this device</h2><div class="storage-row"><span>Used by MediGO</span><b>${new Blob([JSON.stringify(data)]).size > 1024 ? `${(new Blob([JSON.stringify(data)]).size / 1024).toFixed(1)} KB` : `${new Blob([JSON.stringify(data)]).size} B`}</b></div><div class="storage-row"><span>Last backup</span><b>${data.lastBackup ? esc(data.lastBackup) : "Not recorded"}</b></div><div class="actions"><button class="button" data-action="export">Download backup</button><label class="button secondary file-label">Import backup<input id="import-backup" type="file" accept="application/json" hidden></label></div></section><section class="card"><h2>Privacy</h2><p>Your profile and records are stored in this browser on this device. Back up regularly if you need to preserve them.</p><button class="button danger" data-action="delete-profile">Delete this profile</button></section><section class="notice"><b>MediGO is a personal record-keeping tool.</b><p>It does not diagnose, treat or give medical advice. In an emergency, contact your local emergency number or doctor directly.</p></section>`; }

function modalView() { if (!modal) return ""; const is = modal === "doctor", med = modal === "medication", visit = modal === "visit", contact = modal === "contact"; const title = is ? "Add doctor" : med ? "Add medication" : visit ? "Add visit note" : "Add emergency contact"; return `<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="card-heading"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">×</button></div>${is ? `<form id="doctor-form" class="form"><label>Name<input name="name" required></label><label>Specialty<input name="specialty"></label><label>Clinic<input name="clinic"></label><div class="form-row"><label>Phone<input name="phone" type="tel"></label><label>Email<input name="email" type="email"></label></div><label>Next appointment<input name="next" type="date"></label><label>Notes<textarea name="notes"></textarea></label><label class="check"><input name="primary" type="checkbox"> Primary doctor</label><div class="actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button">Save doctor</button></div></form>` : med ? `<form id="med-form" class="form"><label>Name<input name="name" required></label><div class="form-row"><label>Dose<input name="dose" placeholder="e.g. 500 mg" required></label><label>Form<select name="form"><option value="">—</option>${["Tablet", "Capsule", "Syrup", "Injection", "Inhaler", "Drops", "Cream"].map(v => `<option>${v}</option>`).join("")}</select></label></div><label>Frequency<select name="frequency"><option>Daily</option><option>Twice daily</option><option>Three times daily</option><option>Weekly</option><option>Custom times</option></select></label><label>Scheduled times<input name="times" type="time" value="08:00"></label><button type="button" class="text-button" data-action="add-time">＋ Add another time</button><div class="form-row"><label>Start date<input name="start" type="date" value="${today}"></label><label>End date (optional)<input name="end" type="date"></label></div><label>Purpose (optional)<input name="purpose"></label><label>Prescribing doctor<select name="doctor"><option value="">—</option>${p().doctors.map(d => `<option>${esc(d.name)}</option>`).join("")}</select></label><div class="actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button">Add medication</button></div></form>` : visit ? `<form id="visit-form" class="form"><label>Date<input name="date" type="date" value="${today}"></label><label>Doctor<select name="doctor"><option value="">—</option>${p().doctors.map(d => `<option>${esc(d.name)}</option>`).join("")}</select></label><label>What was discussed<textarea name="text" required></textarea></label><div class="actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button">Save visit note</button></div></form>` : `<form id="contact-form" class="form"><label>Name<input name="name" required></label><div class="form-row"><label>Relationship<input name="relationship"></label><label>Phone<input name="phone" type="tel"></label></div><div class="actions"><button type="button" class="button ghost" data-action="close-modal">Cancel</button><button class="button">Save contact</button></div></form>`}</section></div>`; }

function wire() { document.querySelectorAll("[data-page]").forEach(b => b.onclick = () => { page = b.dataset.page; if (page === "doctors") doctorTab = "doctors"; render(); }); document.querySelectorAll("[data-action]").forEach(b => b.onclick = e => { const a = b.dataset.action; if (a === "open-app") { e.preventDefault(); page = data.profiles.length ? "home" : "welcome"; render(); } if (a === "start-profile") { page = data.profiles.length ? "home" : "welcome"; render(); } if (a === "landing") { page = "landing"; render(); } if (a === "continue") { page = "setup"; render(); } if (a === "close-modal") { modal = ""; render(); } if (a === "backdrop" && e.target === b) { modal = ""; render(); } if (a === "profiles") profilePicker(); if (a === "print") window.print(); if (a === "all-sections" || a === "no-sections") { document.querySelectorAll("[data-section]").forEach(i => i.checked = a === "all-sections"); updateSections(); } if (a === "copy-qr") navigator.clipboard?.writeText(document.querySelector("#qr-text").value).then(() => alert("Summary copied. Review it before sharing.")); if (a === "download-qr") downloadText(document.querySelector("#qr-text").value, "medigo-summary.txt"); if (a === "share") { const text = document.querySelector("#qr-text").value; if (navigator.share) navigator.share({ title: "MediGO health summary", text }); else { navigator.clipboard?.writeText(text); alert("Summary copied. Review it before sharing."); } } if (a === "export") exportBackup(); if (a === "delete-profile" && confirm("Delete this profile and its records from this device? This cannot be undone unless you have a backup.")) { data.profiles = data.profiles.filter(z => z.id !== p().id); data.activeProfileId = data.profiles[0]?.id || null; save(); page = data.profiles.length ? "home" : "landing"; render(); } if (a === "toggle-table") { tableMode = !tableMode; render(); } if (a === "apply-range") { const from = document.querySelector("#range-from").value, to = document.querySelector("#range-to").value; if (from && to && from <= to) { window.customRange = [from, to]; render(); } } if (a === "add-time") { const f = document.querySelector("#med-form"); const label = document.createElement("label"); label.textContent = "Additional time"; const input = document.createElement("input"); input.name = "times"; input.type = "time"; input.value = "20:00"; label.append(input); f.querySelector('[name="times"]').parentElement.after(label); } });
 document.querySelector("#accept-disclaimer")?.addEventListener("change", e => { document.querySelector('[data-action="continue"]').disabled = !e.target.checked; }); document.querySelector("#setup-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); const q = { id: uid(), name: f.get("name").trim(), dob: f.get("dob"), blood: f.get("blood"), conditions: f.get("conditions").split(",").map(s => s.trim()).filter(Boolean), allergies: "", guardian: f.get("guardian") === "on", height: "", entries: [], medications: [], doses: {}, doctors: [], questions: [], visitNotes: [], documents: [], contacts: [] }; data.profiles.push(q); data.activeProfileId = q.id; save(); page = "home"; render(); });
 document.querySelector("#entry-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target), t = f.get("tracker"); p().entries.push({ id: uid(), tracker: t, value: f.get("value"), unit: unit(t), date: f.get("date"), note: f.get("note"), time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }); save(); page = "home"; render(); }); document.querySelectorAll("[data-log]").forEach(b => b.onclick = () => { tracker = b.dataset.log; page = "log"; render(); }); document.querySelectorAll("[data-water]").forEach(b => b.onclick = () => { p().waterTotal = Number(p().waterTotal || 0) + Number(b.dataset.water); p().entries.push({ id: uid(), tracker: "Water", value: p().waterTotal, unit: "ml", date: today, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }); save(); render(); });
 document.querySelectorAll("[data-doctor-tab]").forEach(b => b.onclick = () => { doctorTab = b.dataset.doctorTab; render(); }); document.querySelectorAll("[data-modal]").forEach(b => b.onclick = () => { modal = b.dataset.modal; render(); }); document.querySelector("#doctor-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); p().doctors.push({ id: uid(), name: f.get("name"), specialty: f.get("specialty"), clinic: f.get("clinic"), phone: f.get("phone"), email: f.get("email"), next: f.get("next"), notes: f.get("notes"), primary: f.get("primary") === "on" }); save(); modal = ""; render(); }); document.querySelector("#visit-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); p().visitNotes.push({ id: uid(), date: f.get("date"), doctor: f.get("doctor"), text: f.get("text") }); save(); modal = ""; doctorTab = "visits"; render(); }); document.querySelector("#question-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); p().questions.push({ id: uid(), text: f.get("question"), ready: true }); save(); render(); }); document.querySelectorAll("[data-ready]").forEach(i => i.onchange = () => { const q = p().questions.find(z => z.id === i.dataset.ready); q.ready = i.checked; save(); });
 document.querySelector("#med-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); const times = f.getAll("times"); p().medications.push({ id: uid(), name: f.get("name"), dose: f.get("dose"), form: f.get("form"), frequency: f.get("frequency"), times, start: f.get("start"), end: f.get("end"), purpose: f.get("purpose"), doctor: f.get("doctor") }); save(); modal = ""; page = "medications"; render(); }); document.querySelectorAll("[data-dose]").forEach(b => b.onclick = () => { p().doses[`${today}:${b.dataset.dose}`] = b.dataset.status; save(); render(); });
 document.querySelector("#contact-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); p().contacts.push({ id: uid(), name: f.get("name"), relationship: f.get("relationship"), phone: f.get("phone") }); save(); modal = ""; render(); }); document.querySelector("#profile-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target); Object.assign(p(), { name: f.get("name"), dob: f.get("dob"), blood: f.get("blood"), height: f.get("height"), conditions: f.get("conditions").split(",").map(s => s.trim()).filter(Boolean), allergies: f.get("allergies") }); save(); render(); }); document.querySelectorAll("[data-unit]").forEach(i => i.onchange = () => { data.settings[i.dataset.unit] = i.value; save(); render(); }); document.querySelector("#large-text")?.addEventListener("change", e => { data.settings.largeText = e.target.checked; save(); render(); }); document.querySelector("#high-contrast")?.addEventListener("change", e => { data.settings.highContrast = e.target.checked; save(); render(); }); document.querySelector("#asian-bmi")?.addEventListener("change", e => { data.settings.asianBmi = e.target.checked; save(); }); document.querySelector("#import-backup")?.addEventListener("change", importBackup);
 document.querySelectorAll("[data-tracker]").forEach(b => b.onclick = () => { tracker = b.dataset.tracker; render(); }); document.querySelectorAll("[data-range]").forEach(b => b.onclick = () => { range = b.dataset.range === "custom" ? "custom" : Number(b.dataset.range); render(); }); document.querySelectorAll("[data-section]").forEach(i => i.onchange = updateSections); document.querySelectorAll("[data-edit]").forEach(b => b.onclick = () => { const e = p().entries.find(z => z.id === b.dataset.edit); if (!e) return; const value = prompt("Update this entry", e.value); if (value !== null && value.trim()) { e.value = value.trim(); save(); render(); } }); document.querySelectorAll("[data-delete-entry]").forEach(b => b.onclick = () => { if (confirm("Delete this entry?")) { p().entries = p().entries.filter(z => z.id !== b.dataset.deleteEntry); save(); render(); } }); document.querySelectorAll("[data-remove-med]").forEach(b => b.onclick = () => { p().medications = p().medications.filter(z => z.id !== b.dataset.removeMed); save(); render(); }); document.querySelectorAll("[data-remove-doctor]").forEach(b => b.onclick = () => { p().doctors = p().doctors.filter(z => z.id !== b.dataset.removeDoctor); save(); render(); }); document.querySelectorAll("[data-remove-question]").forEach(b => b.onclick = () => { p().questions = p().questions.filter(z => z.id !== b.dataset.removeQuestion); save(); render(); }); document.querySelectorAll("[data-remove-doc]").forEach(b => b.onclick = () => { p().documents = p().documents.filter(z => z.id !== b.dataset.removeDoc); save(); render(); }); document.querySelectorAll("[data-remove-contact]").forEach(b => b.onclick = () => { p().contacts = p().contacts.filter(z => z.id !== b.dataset.removeContact); save(); render(); }); document.querySelectorAll("[data-view-doc]").forEach(b => b.onclick = () => { const d = p().documents.find(z => z.id === b.dataset.viewDoc); if (d?.content) window.open(d.content, "_blank", "noopener"); else alert("This local document preview is unavailable."); }); document.querySelector("#document-form")?.addEventListener("submit", e => { e.preventDefault(); const f = new FormData(e.target), file = f.get("file"); if (!file?.name) return alert("Choose a PDF or photo first."); if (file.size > 5 * 1024 * 1024) return alert("Choose a file smaller than 5 MB."); if (p().documents.length >= 20) return alert("This profile can store up to 20 documents."); const reader = new FileReader(); reader.onload = () => { p().documents.push({ id: uid(), name: file.name, label: f.get("label"), category: f.get("category"), date: f.get("date") || today, size: file.size, content: reader.result }); save(); render(); }; reader.readAsDataURL(file); }); }

function updateSections() { sessionStorage.setItem("medigo-sections", JSON.stringify([...document.querySelectorAll("[data-section]:checked")].map(i => i.dataset.section))); render(); }
function profilePicker() { const names = data.profiles.map((z, i) => `${i + 1}. ${z.name}`).join("\n"); const choice = Number(prompt(`Choose a profile:\n${names}\n\nEnter a number, or Cancel.`)); if (choice > 0 && data.profiles[choice - 1]) { data.activeProfileId = data.profiles[choice - 1].id; save(); render(); } }
function downloadText(text, filename) { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([text], { type: "text/plain" })); a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); }
function exportBackup() { data.lastBackup = new Date().toLocaleString(); save(); const blob = new Blob([JSON.stringify({ format: "medigo-backup", version: 2, exportedAt: new Date().toISOString(), data }, null, 2)], { type: "application/json" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `medigo-backup-${today}.json`; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); }
function importBackup(e) { const file = e.target.files?.[0]; if (!file) return; const r = new FileReader(); r.onload = () => { try { const b = JSON.parse(r.result); if (b.format !== "medigo-backup" || !b.data || !Array.isArray(b.data.profiles)) throw new Error("Unsupported backup file"); if (confirm("Replace this device’s MediGO records with the profiles in this backup?")) { data = b.data; save(); page = data.profiles.length ? "home" : "landing"; render(); } } catch (err) { alert(`Backup was not imported: ${err.message}`); } }; r.readAsText(file); }
if ("serviceWorker" in navigator) navigator.serviceWorker.register("./sw.js").catch(() => {});
render();
